var GPT_IMAGE = {
  "1:1": 0.05268,
  "16:9": 0.0396,
  "9:16": 0.0396,
  "4:3": 0.03612,
  "3:4": 0.03612
};
var NANO_IMAGE = 0.067;
var VIDEO_768P_PER_S = 0.018;
var VIDEO_REF_768P_PER_S = 0.05;
var VIDEO_INCLUDED_IMAGES = 2;
var VIDEO_EXTRA_IMAGE = 0.02;
var HF_VIDEO_768P_PER_S = 18;
var HF_VIDEO_REF_768P_PER_S = 50;
var HF_VIDEO_EXTRA_IMAGE = 20;
